  function isoDay(value) { var d=startDay(value), y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0'); return y+'-'+m+'-'+day; }
  function localInput(date) { var d=new Date(date); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,16); }
  function esc(value) { return String(value==null?'':value).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];}); }
  function el(tag,cls,text){var n=document.createElement(tag);if(cls)n.className=cls;if(text!=null)n.textContent=text;return n;}
  function navButton(text,route){var b=el('button','nav-item',text);b.type='button';b.setAttribute('onclick',"ir('"+route+"')");return b;}
  async function query(builder){var r=await(typeof window.sbTimeout==='function'?window.sbTimeout(builder):builder);if(r&&r.error)throw r.error;return r?r.data:null;}
  async function rpc(name,args){return query(window.sb.rpc(name,args));}
  function message(error){var m=String(error&&(error.message||error.error_description||error.error)||'No se pudo completar la operación.');if(/traslapa|reservado|ya tiene|bloqueado|23P01/i.test(m))return 'Ese horario ya no está disponible. Actualiza la agenda o elige otro.';if(/fuera del horario|disponibilidad/i.test(m))return m;if(/40001|otra sesión/i.test(m))return 'La cita cambió en otra sesión. Actualizamos la agenda para evitar sobrescribirla.';if(/permission|permiso|42501|row-level/i.test(m))return 'Tu rol no permite realizar esta acción.';return m.replace(/^Error:\s*/i,'');}
  function dialogError(text){var d=document.getElementById('schedule-dialog');if(!d||!d.open)return;var actions=d.querySelector('.schedule-dialog-actions');if(!actions)return;var box=d.querySelector('[data-dialog-error]');if(!text){if(box)box.remove();return;}if(!box){box=document.createElement('p');box.className='schedule-dialog-error';box.setAttribute('role','alert');box.dataset.dialogError='true';actions.parentNode.insertBefore(box,actions);}box.textContent=text;box.scrollIntoView({block:'nearest'});}
  function notify(text,tone){if(tone==='error')dialogError(text);var h=document.getElementById('schedule-feedback');if(!h)return;h.innerHTML=text?'<div class="schedule-notice" data-tone="'+esc(tone||'info')+'"><span>'+esc(text)+'</span><button type="button">Cerrar</button></div>':'';var b=h.querySelector('button');if(b)b.onclick=function(){h.replaceChildren();};}
  function byId(rows,id){return rows.find(function(r){return r.id===id;});}
  async function ensurePatients(ids){var have={};state.patients.forEach(function(p){have[p.id]=true;});var missing=Array.from(new Set((ids||[]).filter(function(id){return id&&!have[id];})));for(var i=0;i<missing.length;i+=100){try{var rows=await query(window.sb.from('camila_pacientes').select('id,nombre,apellido,telefono,email').eq('tenant_id',state.tenant).in('id',missing.slice(i,i+100)));(rows||[]).forEach(function(r){state.patients.push(r);});}catch(_){}}}
  function patientName(id){var p=byId(state.patients,id);return p?[p.nombre,p.apellido].filter(Boolean).join(' '):'Paciente';}
  function range(){var start;if(state.view==='day'){start=startDay(state.date);return {start:start,end:plusDays(start,1)};}if(state.view==='agenda'){start=startDay(state.date);return {start:start,end:plusDays(start,14)};}if(state.view==='month'){var first=new Date(state.date.getFullYear(),state.date.getMonth(),1);start=plusDays(startDay(first),-((first.getDay()+6)%7));return {start:start,end:plusDays(start,42)};}start=plusDays(startDay(state.date),-((state.date.getDay()+6)%7));return {start:start,end:plusDays(start,7)};}
  function fmtDate(d,opts){return new Intl.DateTimeFormat('es-MX',opts).format(d);}
  function fmtTime(d){return fmtDate(new Date(d),{hour:'2-digit',minute:'2-digit'});}
  function fmtRange(a){return fmtTime(a.starts_at)+'–'+fmtTime(a.ends_at);}
  function durationLabel(a,s){var minutes=a&&a.starts_at&&a.ends_at?Math.round((new Date(a.ends_at)-new Date(a.starts_at))/60000):Number(s&&s.duration_minutes||0);return minutes?minutes+' min':'Duración por confirmar';}
  function reminderLabel(status,row){if(status==='processing'&&row&&row.provider_reference)return 'Programado en WhatsApp';if(status==='pending'&&row&&row.last_error)return 'En espera';return ({pending:'Pendiente',processing:'En proceso',sent:'Enviado',failed:'Requiere atención',cancelled:'Cancelado'})[status]||status;}
  function remindersChanged(){if(window.SmylReminders)window.SmylReminders.dispatch(true);}
  function activeAppointments(){return state.appointments.filter(function(a){return a.status!=='cancelled';});}

  function capabilities(){var owner=window.miRolEquipo==='dueño';var authId=state.actor;var ids=new Set(state.memberRoles.filter(function(r){return r.user_id===authId;}).map(function(r){return r.role_id;}));var perms=new Set(state.rolePermissions.filter(function(r){return ids.has(r.role_id);}).map(function(r){return r.permission_key;}));state.canManage=owner||perms.has('schedule.manage');state.canReadClinical=owner||perms.has('clinical.read');}

  function renderHeader(){var r=range(),title;if(state.view==='day')title=fmtDate(r.start,{weekday:'long',day:'numeric',month:'long'});else if(state.view==='month')title=fmtDate(state.date,{month:'long',year:'numeric'});else if(state.view==='agenda')title='Próximos 14 días · '+fmtDate(r.start,{day:'numeric',month:'short'});else title=fmtDate(r.start,{day:'numeric',month:'short'})+' — '+fmtDate(plusDays(r.end,-1),{day:'numeric',month:'short',year:'numeric'});document.getElementById('schedule-period').textContent=title;document.querySelectorAll('[data-schedule-view]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.scheduleView===state.view));});}
  function todayAppointments(){var today=isoDay(new Date());return activeAppointments().filter(function(a){return isoDay(a.starts_at)===today;});}
  function renderMetrics(){var todayRows=todayAppointments();var pending=state.requests.filter(function(r){return r.status==='pending';}).length;var reminders=state.reminders.filter(function(r){return isoDay(r.scheduled_for)===isoDay(new Date());}),sent=reminders.filter(function(r){return r.status==='sent';}).length,failed=reminders.filter(function(r){return r.status==='failed';}).length;document.getElementById('schedule-metrics').innerHTML=[['Hoy',todayRows.length,'citas programadas'],['Por llegar',todayRows.filter(function(a){return a.status==='confirmed';}).length,'confirmadas'],['En clínica',todayRows.filter(function(a){return a.status==='arrived'||a.status==='in_progress';}).length,'llegaron o en atención'],['Solicitudes',pending,pending?'requieren revisión':'sin pendientes'],['Recordatorios',reminders.length,failed?failed+' requieren revisión':sent+' enviados']].map(function(x){return '<article><span>'+x[0]+'</span><strong>'+x[1]+'</strong><small>'+x[2]+'</small></article>';}).join('');}
  function renderFocus(){var host=document.getElementById('schedule-focus'),now=Date.now(),visible=range(),today=todayAppointments(),tasks=[];if(now<visible.start.getTime()||now>=visible.end.getTime()){host.innerHTML='<div class="schedule-focus-head"><div><span>OTRO PERIODO</span><h2>Estás consultando otra fecha</h2><p>Vuelve a hoy para revisar las acciones que requieren atención inmediata.</p></div><button type="button" class="btn btn-secondary" data-focus-today>Volver a hoy</button></div>';host.querySelector('[data-focus-today]').onclick=function(){state.date=startDay(new Date());state.view='day';state.tab='calendar';state.loaded=false;load(true);};return;}today.filter(function(a){return a.status==='confirmed'&&new Date(a.starts_at).getTime()<now;}).forEach(function(a){tasks.push({priority:1,label:'Estado pendiente',title:patientName(a.patient_id),detail:fmtTime(a.starts_at)+' · la hora ya pasó',action:'Revisar cita',appointment:a.id});});today.filter(function(a){return a.status==='in_progress'||a.status==='arrived';}).forEach(function(a){tasks.push({priority:a.status==='in_progress'?2:3,label:a.status==='in_progress'?'En atención':'Paciente en clínica',title:patientName(a.patient_id),detail:fmtTime(a.starts_at)+' · '+STATUS[a.status],action:'Abrir cita',appointment:a.id});});state.requests.filter(function(r){return r.status==='pending';}).forEach(function(r){tasks.push({priority:4,label:'Solicitud del asistente',title:patientName(r.patient_id),detail:r.requested_start?'Preferencia · '+fmtDate(new Date(r.requested_start),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Horario por acordar',action:'Revisar solicitud',request:r.id});});state.reminders.filter(function(r){return r.status==='failed'||(r.status==='pending'&&new Date(r.scheduled_for).getTime()<now);}).forEach(function(r){var a=byId(state.appointments,r.appointment_id);tasks.push({priority:5,label:r.status==='failed'?'Recordatorio fallido':'Recordatorio pendiente',title:a?patientName(a.patient_id):'Cita programada',detail:fmtDate(new Date(r.scheduled_for),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}),action:a?'Abrir cita':'Revisar canales',appointment:a&&a.id,channels:!a});});today.filter(function(a){var t=new Date(a.starts_at).getTime();return a.status==='confirmed'&&t>=now&&t<=now+2*60*60*1000;}).forEach(function(a){tasks.push({priority:6,label:'Próxima cita',title:patientName(a.patient_id),detail:fmtTime(a.starts_at)+' · prepara la recepción',action:'Ver cita',appointment:a.id});});today.filter(function(a){return a.status==='no_show';}).forEach(function(a){tasks.push({priority:7,label:'Seguimiento pendiente',title:patientName(a.patient_id),detail:fmtTime(a.starts_at)+' · no asistió',action:'Dar seguimiento',appointment:a.id});});tasks.sort(function(a,b){return a.priority-b.priority;});var pending=tasks.length;host.innerHTML='<div class="schedule-focus-head"><div><span>QUÉ REQUIERE ATENCIÓN</span><h2>'+(pending?pending+' '+(pending===1?'tarea operativa':'tareas operativas'):'La jornada está al día')+'</h2><p>'+(pending?'SMYL ordena lo urgente; el equipo conserva la decisión final.':'No hay citas ni solicitudes pendientes de acción inmediata.')+'</p></div>'+(pending?'<button type="button" class="btn btn-secondary" data-focus-all>Ver agenda del día</button>':'')+'</div>'+(pending?'<div class="schedule-focus-list">'+tasks.slice(0,5).map(function(t){return '<article><div><span>'+esc(t.label)+'</span><strong>'+esc(t.title)+'</strong><small>'+esc(t.detail)+'</small></div><button type="button" data-focus-appointment="'+esc(t.appointment||'')+'" data-focus-request="'+esc(t.request||'')+'" data-focus-channels="'+(t.channels?'true':'false')+'">'+esc(t.action)+'</button></article>';}).join('')+'</div>':'<div class="schedule-focus-empty"><span>✓</span><p>Continúa con la agenda o crea una nueva cita.</p></div>');var all=host.querySelector('[data-focus-all]');if(all)all.onclick=function(){state.date=startDay(new Date());state.view='day';state.tab='calendar';state.loaded=false;load(true);};host.querySelectorAll('.schedule-focus-list button').forEach(function(b){b.onclick=function(){if(b.dataset.focusRequest){state.tab='requests';renderAll();return;}if(b.dataset.focusChannels==='true'){window.ir('conexiones');return;}var a=byId(state.appointments,b.dataset.focusAppointment);if(a)openAppointment(a);};});}
  function filterRow(row){return(!state.branch||row.branch_id===state.branch)&&(!state.professional||row.professional_id===state.professional)&&(!state.room||row.room_id===state.room);}
  function accent(value){var key=String(value||'teal').toLowerCase();return ['teal','blue','amber','coral','violet','rose','green'].includes(key)?key:'teal';}
  function initials(value){return String(value||'P').split(/\s+/).filter(Boolean).slice(0,2).map(function(x){return x.charAt(0);}).join('').toUpperCase();}
  function appointmentCard(a){var s=byId(state.services,a.service_id),p=byId(state.professionals,a.professional_id),room=byId(state.rooms,a.room_id),name=patientName(a.patient_id);return '<button type="button" class="schedule-appointment" data-status="'+a.status+'" data-accent="'+accent(p&&p.color_token)+'" data-appointment="'+a.id+'"><b aria-hidden="true">'+esc(initials(name))+'</b><span>'+fmtRange(a)+' · '+esc(s?s.name:'Servicio')+'</span><strong>'+esc(name)+'</strong><small>'+esc(p?p.display_name:'Profesional')+' · '+esc(room?room.name:'Espacio por asignar')+'</small><i>'+esc(STATUS[a.status]||a.status)+'</i></button>';}
  function blockCard(b){var p=byId(state.professionals,b.professional_id);return '<div class="schedule-block"><span>'+fmtTime(b.starts_at)+'–'+fmtTime(b.ends_at)+'</span><strong>'+esc(b.reason)+'</strong><small>'+esc(p?p.display_name:'Espacio bloqueado')+'</small></div>';}
  function visibleAppointments(){return state.appointments.filter(filterRow).sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);});}
  function bindCalendar(host){host.querySelectorAll('[data-appointment]').forEach(function(b){b.onclick=function(){openAppointment(byId(state.appointments,b.dataset.appointment));};});host.querySelectorAll('[data-book-slot]').forEach(function(b){b.onclick=function(){var start=new Date(b.dataset.bookSlot);openNew(null,null,start,b.dataset.professional||'');};});host.querySelectorAll('[data-open-day]').forEach(function(b){b.onclick=function(){state.date=startDay(new Date(b.dataset.openDay+'T12:00:00'));state.view='day';state.loaded=false;load(true);};});host.querySelectorAll('[data-empty-settings]').forEach(function(b){b.onclick=function(){state.tab='settings';renderAll();};});}
  function dayAvailability(day){var rows=state.hours.filter(function(h){return h.active&&h.weekday===day.getDay()&&(!state.branch||h.branch_id===state.branch)&&(!state.professional||h.professional_id===state.professional);}),ids=new Set(rows.map(function(h){return h.professional_id;})),starts=rows.map(function(h){return h.starts_at.slice(0,5);}).sort(),ends=rows.map(function(h){return h.ends_at.slice(0,5);}).sort();return {rows:rows,count:ids.size,start:starts[0]||'',end:ends[ends.length-1]||'',professional:state.professional||(rows[0]&&rows[0].professional_id)||''};}
  function emptyWeek(host,days){var active=days.map(function(day){return {day:day,availability:dayAvailability(day)};}),available=active.filter(function(x){return x.availability.count;}).length,first=active.find(function(x){return x.availability.count;}),start=first?new Date(first.day):new Date(days[0]);if(first)start.setHours(Number(first.availability.start.slice(0,2))||9,Number(first.availability.start.slice(3,5))||0,0,0);host.className='schedule-calendar week is-empty';host.innerHTML='<section class="schedule-week-empty"><div class="schedule-week-empty-copy"><span class="schedule-empty-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/><path d="m9 15 2 2 4-4"/></svg></span><div><span>SEMANA SIN CITAS</span><h3>No hay citas programadas</h3><p>Estos son horarios configurados del equipo, no espacios libres confirmados. SMYL validará tratamiento, profesional y sillón al guardar.</p></div></div><div class="schedule-week-empty-actions">'+(state.canManage&&first?'<button type="button" class="btn btn-primary" data-book-slot="'+start.toISOString()+'" data-professional="'+esc(first.availability.professional)+'">Preparar primera cita</button>':'')+'<button type="button" class="btn btn-secondary" data-empty-settings>Ver horarios</button></div><div class="schedule-week-availability" aria-label="Horarios configurados de la semana">'+active.map(function(x){var a=x.availability;return '<button type="button" '+(a.count?'data-book-slot="'+(function(){var d=new Date(x.day);d.setHours(Number(a.start.slice(0,2))||9,Number(a.start.slice(3,5))||0,0,0);return d.toISOString();})()+'" data-professional="'+esc(a.professional)+'"':'data-empty-settings')+'><span>'+DAYS[x.day.getDay()]+' '+x.day.getDate()+'</span><strong>'+(a.count?a.start+'–'+a.end:'Sin horario')+'</strong><small>'+(a.count?'Horario de '+a.count+' '+(a.count===1?'profesional':'profesionales'):'Configurar horario')+'</small></button>';}).join('')+'</div><footer><span>'+available+' de 7 días con horario configurado</span><span>El servidor confirma los espacios reales</span></footer></section>';}
  function renderWeek(host,r){var days=[];for(var i=0;i<7;i++)days.push(plusDays(r.start,i));var apps=visibleAppointments(),blocks=state.blocks.filter(function(b){return b.active&&filterRow(b);});if(!apps.length&&!blocks.length){emptyWeek(host,days);return;}host.className='schedule-calendar week';host.innerHTML=days.map(function(day){var key=isoDay(day),dayApps=apps.filter(function(a){return isoDay(a.starts_at)===key;}),dayBlocks=blocks.filter(function(b){return isoDay(b.starts_at)===key;}),availability=dayAvailability(day),emptyStart=new Date(day);emptyStart.setHours(Number(availability.start.slice(0,2))||9,Number(availability.start.slice(3,5))||0,0,0);return '<section class="schedule-day" data-today="'+(key===isoDay(new Date()))+'"><header><span>'+DAYS[day.getDay()]+'</span><strong>'+day.getDate()+'</strong></header><div class="schedule-day-body">'+(dayApps.map(appointmentCard).join('')+dayBlocks.map(blockCard).join('')||(availability.count?'<button type="button" class="schedule-day-empty" data-book-slot="'+emptyStart.toISOString()+'" data-professional="'+esc(availability.professional)+'"><span>Disponible</span><strong>'+availability.start+'–'+availability.end+'</strong><small>Crear cita</small></button>':'<button type="button" class="schedule-day-empty" data-empty-settings><span>Sin horario</span><small>Configurar disponibilidad</small></button>'))+'</div></section>';}).join('');}
