  function hoursIssues(branch,professional,start,end){var out=[];if(!branch)return out;var clinic=state.clinicHours.filter(function(h){return h.active&&h.branch_id===branch.id;}),own=professional?state.hours.filter(function(h){return h.active&&h.professional_id===professional.id&&h.branch_id===branch.id;}):[];if(!clinic.length)out.push('La sucursal no tiene horario semanal configurado. Agrégalo en Agenda, Disponibilidad; sin eso no se puede confirmar ninguna cita.');if(professional&&!own.length)out.push('El profesional no tiene horario semanal en esta sucursal. Agrégalo en Agenda, Disponibilidad.');if(!start||!end)return out;var a=zoned(start,branch.timezone),b=zoned(end,branch.timezone);if(a.day!==b.day)return out;if(clinic.length&&!fitsHours(clinic,a,b))out.push('La cita queda fuera del horario de la sucursal.');if(own.length&&!fitsHours(own,a,b))out.push('La cita queda fuera de la disponibilidad del profesional.');return out;}
