  function plain(v){return String(v==null?'':v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
  function patientLabel(p){return [p.nombre,p.apellido].filter(Boolean).join(' ');}
  function digitsOf(v){return String(v||'').replace(/\D/g,'');}
  function phoneKey(v){var d=digitsOf(v);if(d.length===10)return d;if(d.length===12&&d.slice(0,2)==='52')return d.slice(2);if(d.length===13&&d.slice(0,3)==='521')return d.slice(3);return d.length>=8&&d.length<=15?d:'';}
